CREATE OR REPLACE FUNCTION public.trgfn_sales_note_notify_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $ BEGIN IF COALESCE(current_setting('app.sales_note_correction', true), '') = '1' THEN PERFORM public.enqueue_notification('sales_note_updated','sales_note',NEW.id,jsonb_build_object('code',NEW.code)); PERFORM public.notify_admins('銷貨單已更新','銷貨單 ' || COALESCE(NEW.code, NEW.id::text) || ' 已更新','/admin/sales-notes',NULL); END IF; RETURN NULL; END; $; DROP TRIGGER IF EXISTS trg_sales_note_notify_update ON public.sales_notes; CREATE TRIGGER trg_sales_note_notify_update AFTER UPDATE ON public.sales_notes FOR EACH ROW EXECUTE FUNCTION public.trgfn_sales_note_notify_update();
